public class NumberMathTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<Integer> ints = java.util.List.of(1, 2, 3, 4);
        check("sumOf List<Integer> [1, 2, 3, 4]", 10.0, NumberMath.sumOf(ints));
        java.util.List<Double> doubles = java.util.List.of(1.5, 2.5, 3.0);
        check("sumOf List<Double> [1.5, 2.5, 3.0]", 7.0, NumberMath.sumOf(doubles));
        java.util.List<Long> longs = java.util.List.of(5L, 7L);
        check("sumOf List<Long> [5, 7]", 12.0, NumberMath.sumOf(longs));
        check("sumOf single element", 42.0, NumberMath.sumOf(java.util.List.of(42)));
        check("sumOf mixed signs", -2.5, NumberMath.sumOf(java.util.List.of(-5.0, 2.5)));
        check("sumOf empty list", 0.0, NumberMath.sumOf(new java.util.ArrayList<Integer>()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

